    @Column(name = "grace_days")
    private Integer graceDays;

    /** The sheet's escalation gap, in days: reminding a claim whose previous reminder was at least these days before
     *  the sheet's today escalates it (once per claim); null means off. Not dated. */
    @Column(name = "escalate_after")
    private Integer escalateAfter;

    /** The sheet's review SLA, in days: a REVIEW claim whose review day (the sheet's today when it went to REVIEW)
     *  plus these is before the sheet's today is late for review; null means none. Not dated. */
    @Column(name = "review_sla")
    private Integer reviewSla;

    /** The sheet's mid score threshold, a whole number: with the high one set, a person whose score is at or above it
     *  (and below the high one) is in the MID band; null means none. Not dated. */
    @Column(name = "score_mid")
    public Sheet copyTo(String id, String createdBy, Instant createdAt) {
        Sheet copy = new Sheet(id, createdBy, createdAt, today);
        settings.forEach(s -> copy.settings.add(new DatedSetting(s.getKey(), s.getFrom(), s.getValue())));
        copy.permissions.putAll(permissions);
        copy.policyDate = policyDate;
        copy.periodNumberingFrom = periodNumberingFrom;
        copy.entryDate = entryDate;
        copy.graceDays = graceDays;
        copy.escalateAfter = escalateAfter;
        copy.reviewSla = reviewSla;
        copy.scoreMid = scoreMid;
        copy.scoreHigh = scoreHigh;
        copy.scoreLog = scoreLog;
        copy.fiscalStartMonth = fiscalStartMonth;
        copy.pot = pot;
        copy.alertThreshold = alertThreshold;
    }

    public void setEscalateAfter(Integer escalateAfter) {
        this.escalateAfter = escalateAfter;
    }

    public Integer getReviewSla() {
        return reviewSla;
    }

    public void setReviewSla(Integer reviewSla) {
        this.reviewSla = reviewSla;
    }

    public Integer getScoreMid() {
        return scoreMid;

