    private void refuseOverMaxOpen(Sheet sheet, Claim claim) {
        Integer max = sheet.getMaxOpen();
        if (max == null) {
            return;
        }
        long held = claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheet.getId(), claim.getPersonId()).stream()
